begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id) values('11000000-0000-4000-8000-000000000091'),('11000000-0000-4000-8000-000000000092');
insert into public.nuclei(id,type,name,purpose,created_by) values('21000000-0000-4000-8000-000000000091','amigos','Nome original','Propósito original','11000000-0000-4000-8000-000000000091');
insert into public.nucleus_members(nucleus_id,user_id,role) values('21000000-0000-4000-8000-000000000091','11000000-0000-4000-8000-000000000091','admin'),('21000000-0000-4000-8000-000000000091','11000000-0000-4000-8000-000000000092','member');
select ok(not has_function_privilege('anon','public.update_nucleus_identity(uuid,text,text)','execute'),'anônimo não pode editar');
set local role authenticated;
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000092',true);
select throws_ok($$select public.update_nucleus_identity('21000000-0000-4000-8000-000000000091','name','Outro')$$,'42501','not authorized','participante não administra');
select set_config('request.jwt.claim.sub','11000000-0000-4000-8000-000000000091',true);
select lives_ok($$select public.update_nucleus_identity('21000000-0000-4000-8000-000000000091','name','  Nome novo  ')$$,'admin altera nome');
select is((select name from public.nuclei where id='21000000-0000-4000-8000-000000000091'),'Nome novo','nome normalizado');
select is((select purpose from public.nuclei where id='21000000-0000-4000-8000-000000000091'),'Propósito original','edição de nome preserva propósito');
select lives_ok($$select public.update_nucleus_identity('21000000-0000-4000-8000-000000000091','purpose','Propósito novo')$$,'admin altera propósito');
select is((select name from public.nuclei where id='21000000-0000-4000-8000-000000000091'),'Nome novo','edição de propósito preserva nome');
select throws_ok($$select public.update_nucleus_identity('21000000-0000-4000-8000-000000000091','name',' ')$$,'22023','invalid identity field','nome vazio rejeitado');
select throws_ok($$select public.update_nucleus_identity('21000000-0000-4000-8000-000000000091','name',repeat('a',81))$$,'22023','invalid identity field','nome acima do limite rejeitado');
select throws_ok($$select public.update_nucleus_identity('21000000-0000-4000-8000-000000000091','purpose',repeat('a',501))$$,'22023','invalid identity field','propósito acima do limite rejeitado');
select throws_ok($$select public.update_nucleus_identity('21000000-0000-4000-8000-000000000091','role','admin')$$,'22023','invalid identity field','campo desconhecido rejeitado');
select lives_ok($$select public.close_nucleus('21000000-0000-4000-8000-000000000091','Nome novo')$$,'encerramento existente preservado');
select throws_ok($$select public.update_nucleus_identity('21000000-0000-4000-8000-000000000091','purpose','Reabrir')$$,'42501','not authorized','Núcleo encerrado rejeita edição');
select * from finish();
rollback;
